(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = { timeline: [] };
  if (!document.querySelector('.pj-title')) {
    const cards = [...document.querySelectorAll('.tb-project-main')];
    if (cards[0]) { cards[0].click(); await sleep(3200); }
  }
  out.opened = document.querySelector('.pj-title')?.textContent || null;
  let captured = null;
  const origCreate = URL.createObjectURL.bind(URL);
  URL.createObjectURL = (b) => { captured = b; return origCreate(b); };
  const internals = window.__TAURI_INTERNALS__;
  const origInvoke = internals.invoke;
  const calls = [];
  internals.invoke = function (cmd, args) {
    calls.push(cmd);
    if (cmd === 'save_work_file') return Promise.resolve('D:\\测试目录\\x.ecp');
    return origInvoke.apply(internals, arguments);
  };
  const btn = [...document.querySelectorAll('.pj-head-actions > button')].find((b) => b.textContent.includes('保存作品文件'));
  out.disabledBefore = btn?.disabled ?? null;
  const t0 = Date.now();
  btn?.click();
  for (let i = 0; i < 24; i++) {
    await sleep(500);
    const b2 = [...document.querySelectorAll('.pj-head-actions > button')].find((b) => b.textContent.includes('保存作品文件'));
    out.timeline.push({ ms: Date.now() - t0, disabled: b2?.disabled ?? null, blob: !!captured, calls: calls.length, toast: document.querySelector('.pj-toast')?.textContent || null });
    if (!b2?.disabled && (captured || calls.length)) break;
  }
  URL.createObjectURL = origCreate;
  internals.invoke = origInvoke;
  out.blobSize = captured?.size || null;
  out.calls = calls;
  out.finalToast = document.querySelector('.pj-toast')?.textContent || null;
  return JSON.stringify(out);
})()
